public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }

    // Check if start and end are within bounds
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n ||
        end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // If start equals end, travel is trivially possible
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    // Build adjacency list
    java.util.List<java.util.List<int[]>> adj = new java.util.ArrayList<>();
    for (int i = 0; i < n * n; i++) {
        adj.add(new java.util.ArrayList<>());
    }

    if (paths != null) {
        for (int[] path : paths) {
            if (path == null || path.length < 4) {
                continue;
            }
            int x1 = path[0], y1 = path[1], x2 = path[2], y2 = path[3];
            if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
                continue;
            }
            int idx1 = x1 * n + y1;
            int idx2 = x2 * n + y2;
            adj.get(idx1).add(new int[]{x2, y2});
            adj.get(idx2).add(new int[]{x1, y1});
        }
    }

    // BFS from start to end
    java.util.Queue<int[]> queue = new java.util.LinkedList<>();
    boolean[][] visited = new boolean[n][n];
    queue.offer(start);
    visited[start[0]][start[1]] = true;

    while (!queue.isEmpty()) {
        int[] curr = queue.poll();
        int cx = curr[0], cy = curr[1];

        if (cx == end[0] && cy == end[1]) {
            return "can be travelled";
        }

        int currIdx = cx * n + cy;
        for (int[] neighbor : adj.get(currIdx)) {
            int nx = neighbor[0], ny = neighbor[1];
            if (!visited[nx][ny]) {
                visited[nx][ny] = true;
                queue.offer(new int[]{nx, ny});
            }
        }
    }

    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Input words cannot be null");
    }

    // Convert to uppercase for case-insensitive comparison
    String w1 = word1.toUpperCase();
    String w2 = word2.toUpperCase();

    // Count common letters (each letter counted once per word, i.e., min frequency)
    int[] freq1 = new int[26];
    int[] freq2 = new int[26];

    for (char c : w1.toCharArray()) {
        if (c >= 'A' && c <= 'Z') {
            freq1[c - 'A']++;
        }
    }
    for (char c : w2.toCharArray()) {
        if (c >= 'A' && c <= 'Z') {
            freq2[c - 'A']++;
        }
    }

    int common = 0;
    for (int i = 0; i < 26; i++) {
        common += Math.min(freq1[i], freq2[i]);
    }

    int sumLengths = w1.length() + w2.length();

    // Handle case where sumLengths is 0 (both empty strings)
    if (sumLengths == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    // Reduce the fraction common/sumLengths
    int numerator = common;
    int denominator = sumLengths;

    if (numerator == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    int gcd = gcd(numerator, denominator);
    numerator /= gcd;
    denominator /= gcd;

    if (denominator == 1) {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator;
    } else {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
    }
}

public static String convertDatesToWeekdays(String date) {
    if (date == null || date.trim().isEmpty()) {
        throw new IllegalArgumentException("Date string cannot be null or empty");
    }

    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        throw new IllegalArgumentException("Date must be in the format 'MM dd yyyy'");
    }

    try {
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        if (month < 1 || month > 12) {
            throw new IllegalArgumentException("Month must be between 1 and 12");
        }
        if (day < 1 || day > 31) {
            throw new IllegalArgumentException("Day must be between 1 and 31");
        }
        if (year < 1) {
            throw new IllegalArgumentException("Year must be positive");
        }

        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);
        java.time.DayOfWeek dayOfWeek = localDate.getDayOfWeek();

        String monthName = localDate.getMonth().getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        String dayOfWeekName = dayOfWeek.getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);

        return String.format("%s %d, %d is a %s", monthName, day, year, dayOfWeekName);
    } catch (NumberFormatException e) {
        throw new IllegalArgumentException("Invalid date format: " + e.getMessage());
    } catch (java.time.DateTimeException e) {
        throw new IllegalArgumentException("Invalid date: " + e.getMessage());
    }
}

