    }

    int[] count = new int[k];

    for (int num : arr) {
        int remainder = ((num % k) + k) % k;
        count[remainder]++;
    }

    // Check remainder 0: must be even
    if (count[0] % 2 != 0) {
        return false;
    }

    // Check pairs of remainders i and k-i
    for (int i = 1; i <= k / 2; i++) {
        if (i == k - i) {
            // This happens when k is even and i = k/2
            if (count[i] % 2 != 0) {
                return false;
            }
        } else {
            if (count[i] != count[k - i]) {
                return false;
            }
        }
    }

    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n == 0) return 0;

    // Build adjacency list
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        graph.get(u).add(v);
        graph.get(v).add(u);
    }

    // DFS to calculate minimum time
    // We use a helper method that returns the total time needed for the subtree rooted at node
    // to collect all apples in that subtree and return to the node.
    // If a subtree has no apples, we don't need to visit it, so it contributes 0.
    // If a subtree has apples, we need to go to each child that has apples (or has a subtree with apples)
    // and come back, so each such child adds 2 to the time (1 to go, 1 to return).

    int[] result = new int[1];

    // Use iterative DFS to avoid stack overflow for large n
    // We'll do a post-order traversal
    int[] parent = new int[n];
    Arrays.fill(parent, -1);
    int[] order = new int[n];
    int[] indegree = new int[n];

    // Build parent relationships and get topological order (BFS from root)
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(0);
    parent[0] = -1;
    int idx = 0;
    while (!queue.isEmpty()) {
        int node = queue.poll();
        order[idx++] = node;
        for (int neighbor : graph.get(node)) {
            if (neighbor == parent[node]) continue;
            parent[neighbor] = node;
            queue.offer(neighbor);
        }
    }

    // Process nodes in reverse order (post-order)
    // time[node] = total time needed for subtree rooted at node
    int[] time = new int[n];

    for (int i = n - 1; i >= 0; i--) {
        int node = order[i];
        int totalTime = 0;
        boolean hasAppleInSubtree = hasApple[node];

        for (int neighbor : graph.get(node)) {
            if (neighbor == parent[node]) continue;
            // neighbor is a child
            if (time[neighbor] > 0 || hasApple[neighbor]) {
                // This child's subtree has apples, so we need to visit it
                totalTime += 2 + time[neighbor];
                hasAppleInSubtree = true;
            }
        }

        // If this node's subtree has apples, we need to account for the time
        // But if this is the root, we don't add extra time for the root itself
        // The time for a node is the sum of times for children that have apples, plus 2 for each such child
        // If no child has apples and this node doesn't have an apple, time is 0
        // If this node has an apple or any child has apples, the time is the sum
        // Actually, the logic above already handles it: totalTime accumulates 2 + time[child] for each child with apples
        // If hasAppleInSubtree is true, we keep totalTime, otherwise 0
        time[node] = hasAppleInSubtree ? totalTime : 0;
    }

    return time[0];
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    int remaining = s.length();

    while (remaining > 0) {
        // Ascending pass: pick smallest, then next smallest greater than last, etc.
        for (int i = 0; i < 26 && remaining > 0; i++) {
            if (count[i] > 0) {
                result.append((char) ('a' + i));
                count[i]--;
                remaining--;
            }
        }

        // Descending pass: pick largest, then next largest smaller than last, etc.
        for (int i = 25; i >= 0 && remaining > 0; i--) {
            if (count[i] > 0) {
                result.append((char) ('a' + i));
                count[i]--;
                remaining--;
            }
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    // The average of the whole array is sum / n
    // We need to find a subset of size k (1 <= k <= n-1) such that
    // sum_of_subset / k == sum / n
    // => n * sum_of_subset == k * sum
    // => sum_of_subset = k * sum / n
    // So k * sum must be divisible by n, and sum_of_subset must be an integer.

    // We can use dynamic programming: dp[k][s] = true if we can pick k elements with sum s
    // But s can be large. Let's think of a better approach.

    // Alternative: use a set-based DP where dp[k] is a set of possible sums for k elements.
    // This might be more memory efficient for small n.

    // Let's use a boolean DP: dp[k][s] where s ranges from 0 to sum.
    // But sum can be up to 10000 * 1000 = 10^7, and k up to 1000, so 10^10 which is too large.

    // Better approach: use a set of possible sums for each k.
    // dp[k] = set of sums achievable with k elements.

    // Initialize
    java.util.Set<Integer>[] dp = new java.util.Set[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new java.util.HashSet<>();
    }
    dp[0].add(0);

    for (int num : nums) {
        // Iterate backwards to avoid using the same element multiple times
        for (int k = n; k >= 1; k--) {
            for (int s : dp[k - 1]) {
                dp[k].add(s + num);
            }
        }
    }

    // Now check for each k from 1 to n-1
    for (int k = 1; k < n; k++) {
        // We need sum_of_subset = k * sum / n
        // Check if k * sum is divisible by n
        if ((long) k * sum % n != 0) {
            continue;
        }
        int targetSum = (int) ((long) k * sum / n);
        if (dp[k].contains(targetSum)) {
            return true;
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    if (cost.length == 1) {
        return cost[0];
    }

    int n = cost.length;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;

    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }

    return dp[n];
}

