        } else {
            if (openNeeded > 0) {
                openNeeded--;
            } else {
                insertions++;
            }
        }
    }

    return insertions + openNeeded;
}

public int minOperations(int n) {
    // The array is arr[i] = 2*i + 1 for i in [0, n-1]
    // The target value to make all elements equal is the average of the array.
    // The sum of the array is sum_{i=0}^{n-1} (2*i + 1) = 2 * (n-1)*n/2 + n = n*(n-1) + n = n^2
    // So the average is n^2 / n = n.
    // The target value is n.
    // The number of operations is the sum of the positive differences (or equivalently, the sum of the absolute differences divided by 2, since each operation moves 1 unit from one element to another).
    // Actually, the minimum number of operations is the sum of the amounts we need to subtract from elements greater than n, which equals the sum of the amounts we need to add to elements less than n.
    // For element i, the difference from target n is (2*i + 1) - n.
    // We need to sum the positive differences (or the absolute differences of the lower half).
    // Let's compute the sum of (n - (2*i + 1)) for all i where 2*i + 1 < n.
    // Alternatively, we can compute the sum of absolute differences from n and divide by 2.
    // But a simpler way: the total operations is the sum of the excess over n for all elements that are above n.
    // Elements above n: 2*i + 1 > n => i > (n-1)/2.
    // Let's just compute the sum of (2*i + 1 - n) for i from 0 to n-1 where 2*i+1 > n.
    // Or equivalently, sum of (n - (2*i + 1)) for i where 2*i+1 < n.
    // Let's use the formula: the answer is the sum of the positive parts of (n - (2*i+1)) for i in [0, n-1].
    // Actually, let's just iterate and sum the absolute differences, then divide by 2.
    // But we can do it more efficiently.
    // The array is symmetric around n. The differences are: for i, diff_i = (2*i+1) - n.
    // The sum of all diff_i is 0.
    // The total operations = sum of positive diff_i = (1/2) * sum of |diff_i|.
    // Let's compute sum of |diff_i| for i in [0, n-1].
    // diff_i = 2*i + 1 - n.
    // |diff_i| = |2*i + 1 - n|.
    // Let's find the point where 2*i + 1 = n. If n is odd, i = (n-1)/2. If n is even, there's no exact match.
    // Let's just compute the sum directly.
    long totalDiff = 0;
    for (int i = 0; i < n; i++) {
        int val = 2 * i + 1;
        totalDiff += Math.abs(val - n);
    }
    return (int) (totalDiff / 2);
}

