public String getSmallestString(int n, int k) {
    // We need to construct the lexicographically smallest string of length n with value k.
    // Strategy:
    // 1. Start with all 'a's (value = n).
    // 2. The remaining value to distribute is k - n.
    // 3. To make the string lexicographically smallest, we want the leftmost characters to be as small as possible.
    //    So we should put as much of the remaining value as possible on the rightmost characters.
    // 4. Each character can contribute at most 25 extra (from 'a'=1 to 'z'=26).
    // 5. We iterate from right to left, assigning the maximum possible value (up to 25 extra) to each position,
    //    until the remaining value is exhausted.

    // Edge case: if k < n or k > 26*n, it's impossible, but the problem likely guarantees valid input.
    // We'll assume valid input where n <= k <= 26*n.

    char[] result = new char[n];
    // Initialize all to 'a'
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }

    int remaining = k - n; // extra value to distribute

    // Distribute from right to left
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        // How much can we add to this position? Max 25 (to make it 'z')
        int add = Math.min(remaining, 25);
        result[i] = (char) ('a' + add);
        remaining -= add;
    }

    return new String(result);
}

