        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int maxLen = 0;

    // dp[i][j][0] = horizontal, dp[i][j][1] = vertical, dp[i][j][2] = diagonal, dp[i][j][3] = anti-diagonal
    int[][][] dp = new int[m][n][4];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // Horizontal
                dp[i][j][0] = (j > 0) ? dp[i][j - 1][0] + 1 : 1;
                // Vertical
                dp[i][j][1] = (i > 0) ? dp[i - 1][j][1] + 1 : 1;
                // Diagonal (top-left to bottom-right)
                dp[i][j][2] = (i > 0 && j > 0) ? dp[i - 1][j - 1][2] + 1 : 1;
                // Anti-diagonal (top-right to bottom-left)
                dp[i][j][3] = (i > 0 && j < n - 1) ? dp[i - 1][j + 1][3] + 1 : 1;

                for (int k = 0; k < 4; k++) {
                    if (dp[i][j][k] > maxLen) {
                        maxLen = dp[i][j][k];
                    }
                }
            }
        }
    }

    return maxLen;
}

