    }

    return result;
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    int n = A.length;
    // Count frequencies
    int maxVal = 0;
    for (int v : A) {
        if (v > maxVal) maxVal = v;
    }

    // Precompute which pairs sum to a perfect square
    // Max possible sum is 2 * maxVal, so we need to check up to that
    int maxSum = 2 * maxVal;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }

    // Use backtracking with memoization
    // State: (index, lastValue, remaining counts)
    // Since values can be up to some limit, we use a map for memoization
    // Key: (lastValue, remaining counts encoded as a string or array)

    // For efficiency, let's use a different approach:
    // Group by value, and use backtracking with counts

    // Find unique values and their counts
    java.util.Map<Integer, Integer> countMap = new java.util.HashMap<>();
    for (int v : A) {
        countMap.put(v, countMap.getOrDefault(v, 0) + 1);
    }

    // Get unique values
    int[] uniqueVals = new int[countMap.size()];
    int[] counts = new int[countMap.size()];
    int idx = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
        uniqueVals[idx] = entry.getKey();
        counts[idx] = entry.getValue();
        idx++;
    }

    // Memoization: key is (lastValueIndex, counts array)
    // We'll use a HashMap with a custom key
    java.util.Map<String, Integer> memo = new java.util.HashMap<>();

    // Backtracking function
    // lastIdx: index in uniqueVals of the last placed value, or -1 if none
    // counts: current remaining counts
    int result = backtrack(-1, counts, uniqueVals, isSquare, memo);

    return result;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];
    int maxArea = 0;

    // Find the index of the previous smaller element for each bar
    int[] stack = new int[n];
    int top = -1;
    for (int i = 0; i < n; i++) {
        while (top >= 0 && heights[stack[top]] >= heights[i]) {
            top--;
        }
        left[i] = (top == -1) ? -1 : stack[top];
        stack[++top] = i;
    }

    // Find the index of the next smaller element for each bar
    top = -1;
    for (int i = n - 1; i >= 0; i--) {
        while (top >= 0 && heights[stack[top]] >= heights[i]) {
            top--;
        }
        right[i] = (top == -1) ? n : stack[top];
        stack[++top] = i;
    }

    // Calculate the maximum area
    for (int i = 0; i < n; i++) {
        int width = right[i] - left[i] - 1;
        int area = heights[i] * width;
        if (area > maxArea) {
            maxArea = area;
        }
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int total = rows * cols;
    int[] result = new int[total];

    int idx = 0;
    // There are rows + cols - 1 diagonals
    for (int d = 0; d < rows + cols - 1; d++) {
        if (d % 2 == 0) {
            // Even diagonal: go from bottom-left to top-right
            // Start row: max(0, d - cols + 1)
            // Start col: min(d, cols - 1)
            int startRow = Math.max(0, d - cols + 1);
            int startCol = Math.min(d, cols - 1);
            int r = startRow;
            int c = startCol;
            while (r >= 0 && c < cols) {
                result[idx++] = mat[r][c];
                r--;
                c++;
            }
        } else {
            // Odd diagonal: go from top-right to bottom-left
            // Start row: min(d, rows - 1)
            // Start col: max(0, d - rows + 1)
            int startRow = Math.min(d, rows - 1);
            int startCol = Math.max(0, d - rows + 1);
            int r = startRow;
            int c = startCol;
            while (r < rows && c >= 0) {
                result[idx++] = mat[r][c];
                r++;
                c--;
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }

    char[] digits = String.valueOf(n).toCharArray();
    int len = digits.length;

    // Find the rightmost digit that is smaller than the digit to its right
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit exists, the number is the largest permutation
    if (i < 0) {
        return -1;
    }

    // Find the smallest digit to the right of i that is greater than digits[i]
    int j = len - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }

    // Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the suffix starting from i+1 to get the smallest possible number
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }

    // Convert back to integer
    String resultStr = new String(digits);
    try {
        return Integer.parseInt(resultStr);
    } catch (NumberFormatException e) {
        return -1;
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }

    // Mapping of digits to their center-symmetric counterparts
    Map<Character, Character> symmetricMap = new HashMap<>();
    symmetricMap.put('0', '0');
    symmetricMap.put('1', '1');
    symmetricMap.put('6', '9');
    symmetricMap.put('8', '8');
    symmetricMap.put('9', '6');

    // For even n, we build half and mirror
    // For odd n, we build (n-1)/2 and add a center digit

    int half = n / 2;
    List<String> leftHalf = new ArrayList<>();

    // Generate all possible left halves of length 'half'
    // The first digit cannot be '0' unless n == 1
    generateLeftHalf(leftHalf, half, 0, symmetricMap, n);

    // For each left half, construct the full number
    for (String left : leftHalf) {
        if (n % 2 == 0) {
            // Even length: mirror the left half
            StringBuilder sb = new StringBuilder(left);
            for (int i = left.length() - 1; i >= 0; i--) {
                sb.append(symmetricMap.get(left.charAt(i)));
            }
            result.add(sb.toString());
        } else {
            // Odd length: add a center digit (0, 1, 8)
            for (char center : new char[]{'0', '1', '8'}) {
                StringBuilder sb = new StringBuilder(left);
                sb.append(center);
                for (int i = left.length() - 1; i >= 0; i--) {
                    sb.append(symmetricMap.get(left.charAt(i)));
                }
                result.add(sb.toString());
            }
        }
    }

    return result;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length != 2) {
            return false;
        }
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    // Check if all three points are distinct
    if (x1 == x2 && y1 == y2) return false;
    if (x1 == x3 && y1 == y3) return false;
    if (x2 == x3 && y2 == y3) return false;
    // Check if the three points are collinear using cross product
    // (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1) == 0 means collinear
    long cross = (long)(x2 - x1) * (y3 - y1) - (long)(y2 - y1) * (x3 - x1);
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }

    int[] ugly = new int[n];
    ugly[0] = 1;

    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;

    for (int i = 1; i < n; i++) {
        int min = Math.min(next2, Math.min(next3, next5));
        ugly[i] = min;

        if (min == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (min == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (min == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }

    return ugly[n - 1];
}

